public class SuperBuilderWithArrayTypeParam {
	@lombok.experimental.SuperBuilder
	public static class Parent<A> {
		A field1;
	}

	@lombok.experimental.SuperBuilder
	public static class Child extends Parent<Integer[]> {
		double field3;
	}

